public class Main {
    public static void main(String[] args) {
        for (int meja = 1; meja <= 2; meja++) {
            for (int kursi = 1; kursi <= 2; kursi++) {
                System.out.println("Meja " + meja + " kursi " + kursi);
            }
        }
        for (int i = 1; i <= 3; i++) {
            for (int j = 1; j <= i; j++) {
                System.out.print("[]");
            }
            System.out.println();
        }
        int nomor = 1;
        for (int rak = 1; rak <= 2; rak++) {
            System.out.print("Rak " + rak + ": ");
            for (int botol = 1; botol <= 3; botol++) {
                System.out.print(nomor + " ");
                nomor++;
            }
            System.out.println();
        }
    }
}

